1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	/** Data access for {@link Invoice} rows (JdbcTemplate over the schema in V4__invoices.sql). */
11	@Repository
12	public class InvoiceRepository {
13	
14	    private final JdbcTemplate jdbc;
15	
16	    public InvoiceRepository(JdbcTemplate jdbc) {
17	        this.jdbc = jdbc;
18	    }
19	
20	    private static final org.springframework.jdbc.core.RowMapper<Invoice> MAPPER =
21	            (rs, i) -> new Invoice(rs.getLong("id"), rs.getLong("project_id"),
22	                    rs.getBigDecimal("amount"), rs.getString("status"),
23	                    rs.getString("issued_date"), rs.getString("due_date"),
24	                    rs.getBigDecimal("due"));
25	
26	    // An invoice's amount is the sum of its line items (qty * unit_price); a line-item-less invoice
27	    // totals zero. Derived here so the amount always reflects the current line items.
28	    private static final String AMOUNT_SUM =
29	            "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li"
30	                    + " WHERE li.invoice_id = i.id), 0)";
31	
32	    // What has been paid against the invoice: the sum of its payments (zero when none). The amount
33	    // still due is the invoice amount minus this.
34	    private static final String PAID_SUM =
35	            "COALESCE((SELECT SUM(pm.amount) FROM payments pm"
36	                    + " WHERE pm.invoice_id = i.id), 0)";
37	
38	    private static final String DUE = "(" + AMOUNT_SUM + " - " + PAID_SUM + ")";
39	
40	    // An invoice's status is worked out from its recorded payments, not flipped by hand: it stays
41	    // DRAFT until issued, reads SENT once issued but unpaid, PARTIAL once some (but not all) of the
42	    // amount is paid, and PAID once the payments cover the amount. Derived here so the status always
43	    // reflects the payments on file.
44	    private static final String DERIVED_STATUS =
45	            "CASE WHEN i.status = 'DRAFT' THEN 'DRAFT'"
46	                    + " WHEN " + AMOUNT_SUM + " > 0 AND " + PAID_SUM + " >= " + AMOUNT_SUM
47	                    + " THEN 'PAID'"
48	                    + " WHEN " + PAID_SUM + " > 0 THEN 'PARTIAL'"
49	                    + " ELSE 'SENT' END";
50	
51	    public List<Invoice> findByProject(long projectId) {
52	        return jdbc.query(
53	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
54	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date"
55	                        + " FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
56	                MAPPER, projectId);
57	    }
58	
59	    /** A project's invoices ordered by due date, earliest first (nulls last, id as tiebreak). */
60	    public List<Invoice> findByProjectOrderByDueDate(long projectId) {
61	        return jdbc.query(
62	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
63	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date"
64	                        + " FROM invoices i WHERE i.project_id = ?"
65	                        + " ORDER BY i.due_date ASC NULLS LAST, i.id",
66	                MAPPER, projectId);
67	    }
68	
69	    private static final org.springframework.jdbc.core.RowMapper<InvoiceListing> LISTING_MAPPER =
70	            (rs, i) -> new InvoiceListing(rs.getLong("id"), rs.getLong("project_id"),
71	                    rs.getString("project_name"), rs.getBigDecimal("amount"),
72	                    rs.getString("status"));
73	
74	    // Every invoice joined to its project name, ordered by id. The derived status is an expression,
75	    // so filtering by stage wraps this as a subquery and filters on the aliased column.
76	    private static final String LISTING_SELECT =
77	            "SELECT i.id AS id, i.project_id AS project_id, p.name AS project_name, "
78	                    + AMOUNT_SUM + " AS amount, " + DERIVED_STATUS + " AS status FROM invoices i"
79	                    + " JOIN projects p ON p.id = i.project_id";
80	
81	    /** Every invoice across all projects, joined to its project name, ordered by id. */
82	    public List<InvoiceListing> findAllWithProject() {
83	        return jdbc.query(LISTING_SELECT + " ORDER BY id", LISTING_MAPPER);
84	    }
85	
86	    /**
87	     * One page of the cross-project invoice list, ordered by id. {@code status} narrows to a single
88	     * stage (DRAFT/SENT/PARTIAL/PAID) when non-null/blank; otherwise every stage is included.
89	     */
90	    public List<InvoiceListing> findPage(String status, int limit, int offset) {
91	        if (status == null || status.isBlank()) {
92	            return jdbc.query(LISTING_SELECT + " ORDER BY id LIMIT ? OFFSET ?",
93	                    LISTING_MAPPER, limit, offset);
94	        }
95	        return jdbc.query(
96	                "SELECT id, project_id, project_name, amount, status FROM (" + LISTING_SELECT
97	                        + ") t WHERE t.status = ? ORDER BY id LIMIT ? OFFSET ?",
98	                LISTING_MAPPER, status, limit, offset);
99	    }
100	
101	    /** How many invoices match the (optional) stage filter, across every page. */
102	    public long countAll(String status) {
103	        if (status == null || status.isBlank()) {
104	            return jdbc.queryForObject("SELECT COUNT(*) FROM invoices", Long.class);
105	        }
106	        return jdbc.queryForObject(
107	                "SELECT COUNT(*) FROM (" + LISTING_SELECT + ") t WHERE t.status = ?",
108	                Long.class, status);
109	    }
110	
111	    public Invoice findById(long id) {
112	        List<Invoice> found = jdbc.query(
113	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
114	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date"
115	                        + " FROM invoices i WHERE i.id = ?",
116	                MAPPER, id);
117	        return found.isEmpty() ? null : found.get(0);
118	    }
119	
120	    public Invoice create(long projectId, BigDecimal amount) {
121	        KeyHolder keys = new GeneratedKeyHolder();
122	        jdbc.update(con -> {
123	            var ps = con.prepareStatement(
124	                    "INSERT INTO invoices (project_id, amount) VALUES (?, ?)", new String[] {"id"});
125	            ps.setLong(1, projectId);
126	            ps.setBigDecimal(2, amount);
127	            return ps;
128	        }, keys);
129	        // A freshly created invoice has no payments yet, so the whole amount is still due.
130	        return new Invoice(keys.getKey().longValue(), projectId, amount, "DRAFT", null, null,
131	                amount);
132	    }
133	
134	    /** Flip an invoice from DRAFT to SENT and return the updated row (null if no such invoice). */
135	    public Invoice markSent(long id) {
136	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", id);
137	        return findById(id);
138	    }
139	
140	    /** Flip an invoice to PAID and return the updated row (null if no such invoice). */
141	    public Invoice markPaid(long id) {
142	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", id);
143	        return findById(id);
144	    }
145	}
