package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI (DESIGN.md §3, docs/SUT_CONTRACT.md §4). The file path + one-record-per-line
 * format is a declared, stable contract, like data-testid: features may be rewritten as long as
 * they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Checkpoints assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

-- Invoices carry a payment status (default UNPAID). Marking an invoice paid flips this to PAID.
-- Additive: a new versioned migration alongside the existing invoices table.
ALTER TABLE invoices ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'UNPAID';

-- Invoices move through a lifecycle: DRAFT (default for a new invoice) -> SENT -> PAID.
-- Additive: a new versioned migration that switches the default status from UNPAID to DRAFT.
ALTER TABLE invoices ALTER COLUMN status SET DEFAULT 'DRAFT';

-- An invoice's amount is now derived from its line items (the sum of qty * unit_price), not typed
-- in directly. Relax the stored amount column so an invoice can exist before it has any line items
-- (a total of zero): default it to 0 and drop the positive-amount check. Additive: a new versioned
-- migration alongside the existing invoices table.
ALTER TABLE invoices ALTER COLUMN amount SET DEFAULT 0;
ALTER TABLE invoices DROP CONSTRAINT invoices_amount_positive;

